using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure.Documents;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class TaskNotificationTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public async Task DisposeAsync(){foreach(var source in sources)await source.DisposeAsync();await db.DisposeAsync();}private Task<object?> S(string sql,params(string,object)[]a)=>db.OwnerScalarAsync(sql,a);private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static long V(JsonElement x)=>x.GetProperty("version").GetInt64();
 private async Task<(string Subject,Guid User,Guid Membership)> Person(string role="SALES"){var x=await Staff(db,role);return(x.Subject,(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",x.Membership)))!,x.Membership);}
 private TaskDetails Details(Guid user,DateTimeOffset? reminder=null)=>new("Arrange delivery",user,"Private task contents",DueAt:reminder?.AddHours(1),ReminderAt:reminder);
 private async Task<DateTimeOffset> Clock()=>new((DateTime)(await S("SELECT now()"))!);
 private static async Task<Guid> Device(HttpClient c){var id=Guid.NewGuid();await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(id)),HttpStatusCode.Created);return id;}
 private async Task<JsonElement> Make(HttpClient c,Guid user,DateTimeOffset? reminder=null,string? key=null,Guid? id=null)=>await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(id??Guid.NewGuid(),Details(user,reminder)),key:key),HttpStatusCode.Created);
 private static Task<HttpResponseMessage> Act(HttpClient c,JsonElement t,string action,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/tasks/{Id(t)}/{action}",version:V(t),key:key);
 private static async Task<JsonElement[]> Inbox(HttpClient c)=>(await Get(c,"/crm/messages")).GetProperty("items").EnumerateArray().ToArray();
 private sealed class Sender(PushWorkResult? result=null):IPushSender{public int Calls;public Task<PushWorkResult> SendAsync(JsonElement x,CancellationToken ct){Interlocked.Increment(ref Calls);Assert.DoesNotContain("Private task contents",x.GetRawText());return Task.FromResult(result??new("SUCCEEDED",ProviderId:"projects/test/messages/1"));}}
 private async Task<PushWorker> Worker(Sender sender){var source=NpgsqlDataSource.Create(db.Worker);sources.Add(source);await S("UPDATE crm.push_jobs SET state='CANCELLED'WHERE company_id<>@c AND state IN('PENDING','RETRY','PROCESSING')",("c",db.Company));await S("UPDATE crm.tasks SET reminder_at=NULL WHERE company_id<>@c AND reminder_at IS NOT NULL",("c",db.Company));return new(source,sender);}private readonly List<NpgsqlDataSource>sources=[];
 private async Task<(Guid Device,JsonElement Task,JsonElement Message)> Queued(HttpClient admin,HttpClient recipient,Guid user,DateTimeOffset? reminder=null)
 {var device=await Device(recipient);await Expect(await Send(recipient,HttpMethod.Put,$"/crm/mobile/devices/{device}/push-subscription",new PushSubscription("fcm-test-token-"+Guid.NewGuid(),"ANDROID",true),0),HttpStatusCode.OK);var t=await Make(admin,user,reminder);return(device,t,(await Inbox(recipient)).Single());}
 [Fact]public async Task Task_lifecycle_history_and_personal_message_reads_are_versioned_and_idempotent()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var key=Code();var id=Guid.NewGuid();var t=await Make(c,p.User,key:key,id:id);Assert.True(JsonElement.DeepEquals(t,await Make(c,p.User,key:key,id:id)));Assert.Single(await Inbox(staff));t=await Expect(await Act(staff,t,"start"),HttpStatusCode.OK);t=await Expect(await Act(staff,t,"complete"),HttpStatusCode.OK);Assert.Equal("COMPLETED",t.GetProperty("state").GetString());await Expect(await Act(staff,t,"reopen"),HttpStatusCode.Forbidden);t=await Expect(await Act(c,t,"reopen"),HttpStatusCode.OK);Assert.Equal(4,(await Get(c,$"/crm/tasks/{id}/history")).GetArrayLength());var m=(await Inbox(staff))[0];var readKey=Code();var read=await Expect(await Send(staff,HttpMethod.Put,$"/crm/messages/{Id(m)}/read",new MessageRead(true),V(m),readKey),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(read,await Expect(await Send(staff,HttpMethod.Put,$"/crm/messages/{Id(m)}/read",new MessageRead(true),V(m),readKey),HttpStatusCode.OK)));Assert.Equal(1,(await Get(staff,"/crm/messages?unread=true")).GetProperty("unreadCount").GetInt64());await Expect(await Send(c,HttpMethod.Get,$"/crm/messages/{Id(m)}"),HttpStatusCode.NotFound);}
 [Theory][InlineData("WAREHOUSE")][InlineData("FINANCE")][InlineData("PROCUREMENT")][InlineData("SALES")]
 public async Task Internal_roles_receive_generic_tasks_without_gaining_customer_or_draft_access(string role)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person(role);using var staff=api.Authenticated(p.Subject);var t=await Make(c,p.User);await Get(staff,$"/crm/tasks/{Id(t)}");var device=await Device(staff);var changes=await Get(staff,$"/crm/mobile/devices/{device}/changes?after=0");Assert.Contains(changes.GetProperty("items").EnumerateArray(),x=>x.GetProperty("entityType").GetString()=="TASK");if(role!="SALES")await Expect(await Send(staff,HttpMethod.Get,"/crm/drafts"),HttpStatusCode.Forbidden);}
 [Fact]public async Task Unrelated_user_and_other_company_cannot_read_or_complete_task()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();var peer=await Person();using var other=api.Authenticated(peer.Subject);using var company=api.Authenticated(company:db.OtherCompany);var t=await Make(c,p.User);await Expect(await Send(other,HttpMethod.Get,$"/crm/tasks/{Id(t)}"),HttpStatusCode.Forbidden);await Expect(await Act(other,t,"complete"),HttpStatusCode.Forbidden);await Expect(await Send(company,HttpMethod.Get,$"/crm/tasks/{Id(t)}"),HttpStatusCode.NotFound);Assert.Empty((await Get(other,"/crm/tasks")).GetProperty("items").EnumerateArray());}
 [Fact]public async Task Customer_linked_task_requires_current_assignment_for_creator_and_assignee()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Task client",null));var input=new TaskCreate(Guid.NewGuid(),Details(p.User)with{CustomerId=customer});await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",input),HttpStatusCode.Forbidden);await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@u)",("c",db.Company),("m",p.Membership),("u",customer));var key=Code();var t=await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",input,key:key),HttpStatusCode.Created);using var staff=api.Authenticated(p.Subject);await Get(staff,$"/crm/tasks/{Id(t)}");await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",p.Membership));await Expect(await Send(staff,HttpMethod.Get,$"/crm/tasks/{Id(t)}"),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",input,key:key),HttpStatusCode.Forbidden);Assert.Empty(await Inbox(staff));}
 [Fact]public async Task Reassignment_invalidates_cursor_and_hides_old_assignee_history_from_new_assignee()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();var q=await Person();using var one=api.Authenticated(p.Subject);using var two=api.Authenticated(q.Subject);var t=await Make(c,p.User);var device=await Device(one);var pull=await Get(one,$"/crm/mobile/devices/{device}/changes?after=0");var key=Code();await Expect(await Send(c,HttpMethod.Put,$"/crm/tasks/{Id(t)}",Details(q.User),V(t),key),HttpStatusCode.OK);await Expect(await Send(one,HttpMethod.Get,$"/crm/tasks/{Id(t)}"),HttpStatusCode.Forbidden);var path=$"/crm/mobile/devices/{device}/changes?after={pull.GetProperty("nextSequence").GetInt64()}&auth={pull.GetProperty("auth").GetString()}";await Expect(await Send(one,HttpMethod.Get,path),HttpStatusCode.Conflict);Assert.Single((await Get(two,$"/crm/tasks/{Id(t)}/history")).EnumerateArray());Assert.Empty(await Inbox(one));}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_writes_or_replays_produce_one_history_and_one_notification(bool replay)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var t=await Make(c,p.User);var key=Code();var all=await Task.WhenAll(Act(c,t,"complete",key),Act(c,t,"complete",replay?key:Code()));Assert.Equal(replay?2:1,all.Count(x=>x.StatusCode==HttpStatusCode.OK));if(!replay)Assert.Single(all,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(2,(await Get(c,$"/crm/tasks/{Id(t)}/history")).GetArrayLength());Assert.Equal(2,(await Inbox(staff)).Length);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Offline_operations_share_sequence_and_handle_replay_and_conflicts(bool conflict)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var op=new TaskOperation(Guid.NewGuid(),1,Guid.NewGuid(),"CREATE",Data:Details(db.Actor));var path=$"/crm/mobile/devices/{device}/task-operations";var first=await Expect(await Send(c,HttpMethod.Post,path,op),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(first,await Expect(await Send(c,HttpMethod.Post,path,op),HttpStatusCode.OK)));var next=new TaskOperation(Guid.NewGuid(),2,op.Id,"COMPLETE",conflict?99:1);var result=await Expect(await Send(c,HttpMethod.Post,path,next),HttpStatusCode.OK);Assert.Equal(conflict?"CONFLICT":"APPLIED",result.GetProperty("status").GetString());await Expect(await Send(c,HttpMethod.Post,$"/crm/mobile/devices/{device}/operations",new MobileOperation(Guid.NewGuid(),3,Guid.NewGuid(),"CREATE",Kind:"CUSTOMER",Data:new("Offline customer",Code:Code()))),HttpStatusCode.OK);Assert.Equal(3L,await S("SELECT last_sequence FROM crm.mobile_devices WHERE company_id=@c AND id=@d",("c",db.Company),("d",device)));}
 [Theory][InlineData("title")][InlineData("assignee")][InlineData("reminder")][InlineData("branch")][InlineData("priority")]
 public async Task Invalid_tasks_do_not_create_history_or_messages(string variant)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=Details(db.Actor);x=variant switch{"title"=>x with{Title=" "},"assignee"=>x with{AssigneeId=Guid.Empty},"reminder"=>x with{ReminderAt=DateTimeOffset.UtcNow},"branch"=>x with{BranchId=Guid.NewGuid()},_=>x with{Priority="BAD"}};await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(Guid.NewGuid(),x)),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM crm.task_history WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Concurrent_due_reminders_are_once_per_generation_and_reschedule_or_reopen_can_remind_again()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var reminder=(await Clock()).AddMinutes(-2);var t=await Make(c,p.User,reminder);var w1=await Worker(new());var w2=await Worker(new());await Task.WhenAll(w1.DeliverRemindersAsync(),w2.DeliverRemindersAsync());Assert.Single(await Inbox(staff),m=>m.GetProperty("event").GetString()=="REMINDER");await w1.DeliverRemindersAsync();t=await Expect(await Act(staff,t,"complete"),HttpStatusCode.OK);await w1.DeliverRemindersAsync();t=await Expect(await Act(c,t,"reopen"),HttpStatusCode.OK);await w1.DeliverRemindersAsync();Assert.Equal(2,(await Inbox(staff)).Count(m=>m.GetProperty("event").GetString()=="REMINDER"));Assert.Equal(2L,await S("SELECT count(*)FROM crm.reminder_deliveries WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Completing_before_due_suppresses_reminder_and_no_ledger_is_touched()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var t=await Make(c,db.Actor,(await Clock()).AddMinutes(-1));await Act(c,t,"complete");await(await Worker(new())).DeliverRemindersAsync();Assert.Equal(0L,await S("SELECT count(*)FROM crm.reminder_deliveries WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));var centre=await Get(c,"/crm/action-centre");Assert.Equal(0,centre.GetProperty("tasks").GetProperty("open").GetInt64());}
 [Fact]public async Task Personal_note_follow_only_notifies_current_authorized_followers_and_never_copies_note_text()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person("OFFICE");using var staff=api.Authenticated(p.Subject);var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Notes client",null));var id=Guid.NewGuid();await Expect(await Send(c,HttpMethod.Post,"/crm/collaboration",new CollaborationCreate(id,"NOTE",customer,null,JsonSerializer.SerializeToElement(new CustomerNote("Sensitive note"),ApiJson.Options))),HttpStatusCode.Created);await Expect(await Send(staff,HttpMethod.Put,$"/crm/notes/{id}/follow",new NoteFollow(true),0),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Put,$"/crm/collaboration/{id}",new CustomerNote("New sensitive text"),1),HttpStatusCode.OK);var m=Assert.Single(await Inbox(staff));Assert.DoesNotContain("sensitive",m.GetRawText());await Expect(await Send(c,HttpMethod.Put,$"/crm/collaboration/{id}",new CustomerNote("Private now","PRIVATE"),2),HttpStatusCode.OK);Assert.Empty(await Inbox(staff));await Expect(await Send(staff,HttpMethod.Get,$"/crm/messages/{Id(m)}"),HttpStatusCode.NotFound);}
 [Theory][InlineData("SUCCEEDED")][InlineData("RETRY")][InlineData("FAILED")][InlineData("UNKNOWN")]
 public async Task Push_worker_records_provider_result_and_bounded_retry_without_repeating_business_action(string state)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);var sender=new Sender(new(state,state=="SUCCEEDED"?null:"test_error",state=="SUCCEEDED"?"projects/t/messages/1":null));var worker=await Worker(sender);Assert.True(await worker.ProcessOneAsync());Assert.False(await worker.ProcessOneAsync());Assert.Equal(1,sender.Calls);var jobs=await Get(staff,$"/crm/messages/{Id(x.Message)}/push");Assert.Equal(state,jobs[0].GetProperty("state").GetString());Assert.Equal(1L,await S("SELECT count(*)FROM crm.push_attempts WHERE company_id=@c",("c",db.Company)));Assert.Single((await Get(c,$"/crm/tasks/{Id(x.Task)}/history")).EnumerateArray());}
 [Theory][InlineData("device")][InlineData("preferences")][InlineData("subscription")][InlineData("membership")][InlineData("read")][InlineData("delete")]
 public async Task Revocation_or_reading_cancels_queued_push_before_sender_is_called(string change)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);switch(change){case"device":await Expect(await Send(staff,HttpMethod.Delete,$"/crm/mobile/devices/{x.Device}"),HttpStatusCode.OK);break;case"preferences":await Expect(await Send(staff,HttpMethod.Put,"/crm/notification-preferences",new PushPreferences(false,true,true),0),HttpStatusCode.OK);break;case"subscription":await Expect(await Send(staff,HttpMethod.Put,$"/crm/mobile/devices/{x.Device}/push-subscription",new PushSubscription("fcm-replacement-token-"+Guid.NewGuid(),"ANDROID",false),1),HttpStatusCode.OK);break;case"membership":await S("UPDATE identity.memberships SET active=false WHERE company_id=@c AND id=@m",("c",db.Company),("m",p.Membership));break;case"read":await Expect(await Send(staff,HttpMethod.Put,$"/crm/messages/{Id(x.Message)}/read",new MessageRead(true),1),HttpStatusCode.OK);break;default:await Expect(await Act(c,x.Task,"delete"),HttpStatusCode.OK);break;}var sender=new Sender();var worker=await Worker(sender);await worker.ProcessOneAsync();Assert.Equal(0,sender.Calls);Assert.Equal("CANCELLED",await S("SELECT state FROM crm.push_jobs WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Unknown_push_requires_explicit_duplicate_acknowledgement_before_retry()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);await(await Worker(new(new("UNKNOWN","uncertain")))).ProcessOneAsync();var job=(await Get(staff,$"/crm/messages/{Id(x.Message)}/push"))[0].GetProperty("jobId").GetGuid();await Expect(await Send(staff,HttpMethod.Post,$"/crm/push/jobs/{job}/retry",new PushRetry("UNKNOWN",false)),HttpStatusCode.UnprocessableEntity);var key=Code();await Expect(await Send(staff,HttpMethod.Post,$"/crm/push/jobs/{job}/retry",new PushRetry("UNKNOWN",true),key:key),HttpStatusCode.OK);await Expect(await Send(staff,HttpMethod.Post,$"/crm/push/jobs/{job}/retry",new PushRetry("UNKNOWN",true),key:key),HttpStatusCode.OK);var sender=new Sender();await(await Worker(sender)).ProcessOneAsync();Assert.Equal(1,sender.Calls);Assert.Equal(2L,await S("SELECT count(*)FROM crm.push_attempts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Token_never_appears_in_views_audit_or_idempotency_response_and_cannot_be_taken_over()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Device(c);var token="super-secret-push-token-"+Guid.NewGuid();var x=await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{d}/push-subscription",new PushSubscription(token,"IOS",true),0),HttpStatusCode.OK);Assert.DoesNotContain(token,x.GetRawText());var d2=await Device(c);await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{d2}/push-subscription",new PushSubscription(token,"IOS",true),0),HttpStatusCode.Conflict);await using var con=new NpgsqlConnection(db.App);await con.OpenAsync();await using var cmd=new NpgsqlCommand("SELECT token FROM crm.push_subscriptions",con);Assert.Equal("42501",(await Assert.ThrowsAsync<PostgresException>(()=>cmd.ExecuteScalarAsync())).SqlState);Assert.Equal(0L,await S("SELECT count(*)FROM platform.audit_events WHERE company_id=@c AND details::text LIKE @token",("c",db.Company),("token","%"+token+"%")));}
 [Fact]public async Task Expired_processing_lease_becomes_unknown_and_is_not_automatically_resent()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);await Queued(c,staff,p.User);await S("UPDATE crm.push_jobs SET state='PROCESSING',attempts=1,lease_token=gen_random_uuid(),lease_until=now()-interval '1 second'WHERE company_id=@c",("c",db.Company));var sender=new Sender();Assert.False(await(await Worker(sender)).ProcessOneAsync());Assert.Equal("UNKNOWN",await S("SELECT state FROM crm.push_jobs WHERE company_id=@c",("c",db.Company)));Assert.Equal(0,sender.Calls);}
 [Fact]public async Task Late_audit_failure_rolls_back_task_history_message_and_push_queue_then_same_key_retries()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();var id=Guid.NewGuid();var key=Code();await S($"CREATE FUNCTION crm.test_c06_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='crm.tasks_create'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c06_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_c06_fail()");try{await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(id,Details(p.User)),key:key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM crm.tasks WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.notification_messages WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c06_fail ON platform.audit_events;DROP FUNCTION crm.test_c06_fail()");}await Make(c,p.User,key:key,id:id);}
 [Fact]public async Task Deleted_task_cannot_leak_cached_detail_update_or_create_content()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var key=Code();var id=Guid.NewGuid();var t=await Make(c,db.Actor,key:key,id:id);var deleteKey=Code();var deleted=await Expect(await Act(c,t,"delete",deleteKey),HttpStatusCode.OK);Assert.Equal(JsonValueKind.Null,deleted.GetProperty("title").ValueKind);await Expect(await Act(c,t,"delete",deleteKey),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(id,Details(db.Actor)),key:key),HttpStatusCode.NotFound);}
