 [Fact]public async Task Hidden_task_create_collision_does_not_reveal_body_or_server_version()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var t=await Make(c,db.Actor);var device=await Device(staff);var result=await Expect(await Send(staff,HttpMethod.Post,$"/crm/mobile/devices/{device}/task-operations",new TaskOperation(Guid.NewGuid(),1,Id(t),"CREATE",Data:Details(p.User))),HttpStatusCode.OK);Assert.Equal("CONFLICT",result.GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,result.GetProperty("serverVersion").ValueKind);Assert.DoesNotContain("Private task contents",result.GetRawText());}
 [Fact]public async Task Automatic_push_retries_stop_at_five_attempts_and_manual_retry_cannot_reset_budget()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);await S("UPDATE crm.push_jobs SET attempts=4 WHERE company_id=@c",("c",db.Company));var sender=new Sender(new("RETRY","provider_busy"));await(await Worker(sender)).ProcessOneAsync();var job=(await Get(staff,$"/crm/messages/{Id(x.Message)}/push"))[0];Assert.Equal("FAILED",job.GetProperty("state").GetString());Assert.Equal(5,job.GetProperty("attempts").GetInt32());await Expect(await Send(staff,HttpMethod.Post,$"/crm/push/jobs/{job.GetProperty("jobId").GetGuid()}/retry",new PushRetry("FAILED",false)),HttpStatusCode.Conflict);}
 [Fact]public async Task Concurrent_worker_claims_use_one_lease_and_stale_completion_is_fenced()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);await Worker(new());async Task<(Guid,Guid)?> Claim(){await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var cmd=new NpgsqlCommand("SELECT job_id,lease FROM crm.claim_push()",con);await using var rd=await cmd.ExecuteReaderAsync();return await rd.ReadAsync()?(rd.GetGuid(0),rd.GetGuid(1)):null;}var both=await Task.WhenAll(Claim(),Claim());var lease=Assert.Single(both,x=>x.HasValue)!.Value;await S("UPDATE crm.push_jobs SET lease_until=now()-interval '1 second'WHERE id=@id",("id",lease.Item1));Assert.Null(await Claim());await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var done=new NpgsqlCommand("SELECT crm.finish_push(@id,@lease,'FAILED','stale',NULL,0)",con);done.Parameters.AddWithValue("id",lease.Item1);done.Parameters.AddWithValue("lease",lease.Item2);Assert.Equal("HR409",(await Assert.ThrowsAsync<PostgresException>(()=>done.ExecuteScalarAsync())).SqlState);Assert.Equal("UNKNOWN",await S("SELECT state FROM crm.push_jobs WHERE id=@id",("id",lease.Item1)));}
 [Fact]public async Task Same_owner_may_move_token_after_revoking_old_device_and_cannot_replay_registration_on_revoked_device()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var token="rotation-token-"+Guid.NewGuid();var key=Code();await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{device}/push-subscription",new PushSubscription(token,"IOS",true),0,key),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Delete,$"/crm/mobile/devices/{device}"),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{device}/push-subscription",new PushSubscription(token,"IOS",true),0,key),HttpStatusCode.Forbidden);var next=await Device(c);await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{next}/push-subscription",new PushSubscription(token,"IOS",true),0),HttpStatusCode.OK);Assert.Equal(1L,await S("SELECT count(*)FROM crm.push_subscriptions WHERE company_id=@c AND token=@t AND enabled",("c",db.Company),("t",token)));}
 [Fact]public async Task Unregistered_token_disables_only_current_subscription_and_preferences_do_not_suppress_inbox()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);await(await Worker(new(new("FAILED","push_token_unregistered")))).ProcessOneAsync();Assert.False((await Get(staff,$"/crm/mobile/devices/{x.Device}/push-subscription")).GetProperty("enabled").GetBoolean());await Expect(await Send(staff,HttpMethod.Put,"/crm/notification-preferences",new PushPreferences(false,false,false),0),HttpStatusCode.OK);await Make(c,p.User);Assert.Equal(2,(await Inbox(staff)).Length);Assert.Equal(1L,await S("SELECT count(*)FROM crm.push_jobs WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Completed_task_cancels_queued_reminder_push_but_keeps_inbox_history()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User,(await Clock()).AddMinutes(-1));var sender=new Sender();var worker=await Worker(sender);await worker.ProcessOneAsync();await worker.DeliverRemindersAsync();await Expect(await Act(staff,x.Task,"complete"),HttpStatusCode.OK);Assert.True(await worker.ProcessOneAsync());Assert.Equal(1,sender.Calls);var reminder=Assert.Single(await Inbox(staff),m=>m.GetProperty("event").GetString()=="REMINDER");Assert.Equal("CANCELLED",(await Get(staff,$"/crm/messages/{Id(reminder)}/push"))[0].GetProperty("state").GetString());}
 [Fact]public async Task Task_only_user_cannot_pull_legacy_drafts_even_if_also_creator_of_one()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Expect(await Send(c,HttpMethod.Post,"/crm/drafts",new CrmDraftInput(Guid.NewGuid(),"CUSTOMER",null,new("Legacy private prospect",Code:Code()))),HttpStatusCode.Created);var device=await Device(c);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='crm.drafts.read'",("c",db.Company));var pull=await Get(c,$"/crm/mobile/devices/{device}/changes?after=0");Assert.DoesNotContain("Legacy private prospect",pull.GetRawText());Assert.DoesNotContain(pull.GetProperty("items").EnumerateArray(),x=>x.GetProperty("entityType").GetString()=="DRAFT");}
 [Fact]public async Task Action_centre_payables_match_existing_aging_and_unprivileged_staff_cannot_see_financial_items()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Htt.Infrastructure.CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,"NON_CASH",DatabaseFixture.Issuer,db.Subject);var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Action supplier",null));var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@c,@code,'Action expense','EXPENSE')RETURNING id",("c",db.Company),("code",Code())))!;var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code='GST'",("c",db.Company)))!;var today=DateOnly.FromDateTime((await Clock()).UtcDateTime);var bill=await Expect(await Send(c,HttpMethod.Post,"/supplier-expense-bills",new Htt.Host.Api.Purchasing.ExpenseBillInput(supplier,Code(),today,today,today,[new(account,"Expense",100,10,tax)],Code(),today)),HttpStatusCode.Created);var centre=await Get(c,"/crm/action-centre");var item=Assert.Single(centre.GetProperty("dueFinancialItems").EnumerateArray());Assert.Equal("AP",item.GetProperty("side").GetString());Assert.Equal(110,D(item.GetProperty("outstanding")));var aging=await Get(c,$"/accounting/reports/payables-aging?asOf={today:yyyy-MM-dd}");Assert.Equal(D(aging.GetProperty("totals").GetProperty("outstanding")),D(item.GetProperty("outstanding")));var p=await Person("WAREHOUSE");using var staff=api.Authenticated(p.Subject);var scoped=await Get(staff,"/crm/action-centre");Assert.Empty(scoped.GetProperty("dueFinancialItems").EnumerateArray());Assert.False(scoped.GetProperty("financialItemsAuthorized").GetBoolean());}


 [Fact]public async Task Assignee_directory_exposes_only_active_eligible_company_members_and_honours_customer_scope()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Directory client",null));var all=(await Get(c,"/crm/task-assignees")).GetProperty("items").EnumerateArray().ToArray();Assert.Contains(all,x=>x.GetProperty("userId").GetGuid()==p.User);Assert.DoesNotContain("issuer",JsonSerializer.Serialize(all));var scoped=(await Get(c,$"/crm/task-assignees?customerId={customer}")).GetProperty("items");Assert.DoesNotContain(scoped.EnumerateArray(),x=>x.GetProperty("userId").GetGuid()==p.User);using var staff=api.Authenticated(p.Subject);await Expect(await Send(staff,HttpMethod.Get,$"/crm/task-assignees?customerId={customer}"),HttpStatusCode.Forbidden);await S("UPDATE identity.memberships SET active=false WHERE company_id=@c AND id=@m",("c",db.Company),("m",p.Membership));Assert.DoesNotContain((await Get(c,"/crm/task-assignees")).GetProperty("items").EnumerateArray(),x=>x.GetProperty("userId").GetGuid()==p.User);}
 [Fact]public async Task Follow_state_is_recoverable_and_unfollowing_cancels_pending_note_push()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person("OFFICE");using var staff=api.Authenticated(p.Subject);var device=await Device(staff);await Expect(await Send(staff,HttpMethod.Put,$"/crm/mobile/devices/{device}/push-subscription",new PushSubscription("note-token-"+Guid.NewGuid(),"IOS",true),0),HttpStatusCode.OK);var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Follow client",null));var note=await Expect(await Send(c,HttpMethod.Post,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",customer,null,JsonSerializer.SerializeToElement(new CustomerNote("First"),ApiJson.Options))),HttpStatusCode.Created);var id=Id(note);Assert.Equal(0,V(await Get(staff,$"/crm/notes/{id}/follow")));await Expect(await Send(staff,HttpMethod.Put,$"/crm/notes/{id}/follow",new NoteFollow(true),0),HttpStatusCode.OK);Assert.Equal(1,V(await Get(staff,$"/crm/notes/{id}/follow")));await Expect(await Send(c,HttpMethod.Put,$"/crm/collaboration/{id}",new CustomerNote("Second"),1),HttpStatusCode.OK);await Expect(await Send(staff,HttpMethod.Put,$"/crm/notes/{id}/follow",new NoteFollow(false),1),HttpStatusCode.OK);var sender=new Sender();await(await Worker(sender)).ProcessOneAsync();Assert.Equal(0,sender.Calls);Assert.Single(await Inbox(staff));}
 [Fact]public async Task Maximum_documented_token_length_uses_fixed_size_uniqueness_key()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var token=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(2048));await Expect(await Send(c,HttpMethod.Put,$"/crm/mobile/devices/{device}/push-subscription",new PushSubscription(token,"WEB",true),0),HttpStatusCode.OK);Assert.Equal(32L,await S("SELECT octet_length(token_hash)::bigint FROM crm.push_subscriptions WHERE company_id=@c AND device_id=@d",("c",db.Company),("d",device)));}

 [Fact]public async Task Token_rotation_moves_only_unsent_work_to_new_generation_and_preserves_inbox_identity()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Person();using var staff=api.Authenticated(p.Subject);var x=await Queued(c,staff,p.User);await Expect(await Send(staff,HttpMethod.Put,$"/crm/mobile/devices/{x.Device}/push-subscription",new PushSubscription("new-rotation-token-"+Guid.NewGuid(),"ANDROID",true),1),HttpStatusCode.OK);var sender=new Sender();var worker=await Worker(sender);while(await worker.ProcessOneAsync()){}Assert.Equal(1,sender.Calls);Assert.Single(await Inbox(staff));var jobs=(await Get(staff,$"/crm/messages/{Id(x.Message)}/push")).EnumerateArray().ToArray();Assert.Equal(2,jobs.Length);Assert.Single(jobs,j=>j.GetProperty("state").GetString()=="SUCCEEDED");Assert.Single(jobs,j=>j.GetProperty("state").GetString()=="CANCELLED");}

